package com.huntersystem.app
import org.json.JSONObject

class Goals(val catalog:Catalog){
 private val lex=linkedMapOf(
 "build" to listOf("cuerpo\\s+estetic[oa]","estetic[oa]","tonific","definicion\\s+muscular","definir\\s+(?:mi\\s+)?(?:cuerpo|musculos)","ganar\\s+muscul","masa\\s+muscular","hipertrof","fuerza","fortalec","muscul","pecho|espalda|biceps|triceps|gluteos|abdomen|marcar\\s+abdomen"),
 "fitness" to listOf("resistencia\\s+(?:cardiovascular|aerobica|fisica)","cardio","bajar\\s+(?:de\\s+)?peso","quemar\\s+grasa","condicion\\s+fisica","aguantar\\s+mas","correr\\s+mas"),
 "athletic" to listOf("agilidad","agil(?:es)?","coordinacion","potencia","velocidad","reaccion","sprint","salto","explosiv","deportiv"),
 "movement" to listOf("movilidad","flexibilidad","estiramiento","equilibrio","postura","control\\s+motor","rango\\s+de\\s+movimiento"),
 "habit" to listOf("constancia","disciplina","habito","bienestar","rutina\\s+(?:estable|diaria)","ser\\s+activo"),
 "adapted" to listOf("actividad\\s+adaptada","retomar\\s+(?:el\\s+)?entrenamiento","regresar\\s+a\\s+entrenar","solo\\s+sentado"))
 private val targets=mapOf("build" to "muscle","fitness" to "endurance","athletic" to "athletic","movement" to "mobility","habit" to "general","adapted" to "returning")
 fun interpret(text:String,chosen:String="habit"):JSONObject{
  val raw=normalize(text);val positive=raw.replace(Regex("\\b(?:no quiero|no deseo|no busco|evitar|evito|sin interes en)\\s+[^.;,]+")," ")
  val hits=lex.mapNotNull{(g,res)->val ms=res.mapNotNull{Regex(it).find(positive)};if(ms.isEmpty())null else Triple(g,ms.minOf{it.range.first},ms.size)}.sortedWith(compareBy<Triple<String,Int,Int>>{it.second}.thenByDescending{it.third});val primary=hits.firstOrNull()?.first?:chosen.takeIf{it in targets}?:"habit"
  val focus=when{Regex("\\b(?:piernas?|gluteos?|tren\\s+inferior)\\b").containsMatchIn(positive)->"lower";Regex("\\b(?:brazos?|pecho|hombros?|tren\\s+superior)\\b").containsMatchIn(positive)->"upper";Regex("\\b(?:abdomen|core|zona\\s+media)\\b").containsMatchIn(positive)->"core";else->"full"}
  val restrictions=JSONObject();val patterns=mapOf("noImpact" to "\\b(?:sin\\s+(?:saltos?|impacto)|evitar\\s+(?:los\\s+)?saltos?|no\\s+(?:quiero|puedo)\\s+salt(?:ar|os?))\\b","noFloor" to "\\b(?:sin\\s+suelo|no\\s+(?:puedo|quiero)\\s+(?:tumbarme|arrodillarme))\\b","noOverhead" to "\\b(?:no\\s+(?:puedo|quiero)\\s+levantar\\s+los\\s+brazos|sin\\s+elevar\\s+los\\s+brazos)\\b","noLoad" to "\\b(?:sin\\s+(?:mancuernas|pesas|carga)|no\\s+(?:puedo|quiero)\\s+usar\\s+pesas)\\b","noWrist" to "\\b(?:sin\\s+apoyo\\s+en\\s+(?:las\\s+)?manos|no\\s+(?:puedo|quiero)\\s+apoyar\\s+las\\s+manos)\\b","noKnee" to "\\b(?:sin\\s+flexionar\\s+(?:las\\s+)?rodillas|no\\s+(?:puedo|quiero)\\s+doblar\\s+(?:las\\s+)?rodillas)\\b","seatedOnly" to "\\b(?:solo|unicamente)\\s+(?:estar\\s+)?sentado\\b")
  for((k,re)in patterns)if(Regex(re).containsMatchIn(raw))restrictions.put(k,true)
  var target=targets[primary]?:"general";if(primary=="build")target=when(focus){"upper","lower","core"->focus;else->if(Regex("\\bfuerza\\b").containsMatchIn(positive)&&!Regex("estetic|muscul|tonific|hipertrof|defin").containsMatchIn(positive))"strength" else "muscle"};if(primary=="fitness"&&Regex("bajar\\s+(?:de\\s+)?peso|quemar\\s+grasa").containsMatchIn(positive))target="activity";if(primary=="movement")target=when{Regex("equilibrio").containsMatchIn(positive)->"balance";Regex("flexibil|estiramiento").containsMatchIn(positive)->"flexibility";Regex("postura").containsMatchIn(positive)->"posture";else->target};if(primary=="habit"&&restrictions.b("noImpact"))target="lowimpact";if(primary=="adapted"&&"solo sentado" in positive)target="seated"
  if(!catalog.editorial.o("goalPlans").has(target))target=targets[primary]?:"general"
  val medical=Regex("\\b(?:lesion(?:es)?|hernia|fractura|cirugia|dolor|duele|molestia|rehabilitacion)\\b").containsMatchIn(raw.replace(Regex("\\b(?:sin|no\\s+tengo)\\s+(?:ninguna?\\s+)?(?:lesiones?|dolor|molestias?)\\b")," "))
  return obj("primary" to primary,"alternatives" to arr(hits.map{it.first}),"target" to target,"focus" to focus,"restrictions" to restrictions,"medical" to medical,"recognized" to hits.size)
 }
 fun apply(p:JSONObject,manual:Boolean=false):JSONObject{val out=p.copyJson();val result=interpret(p.s("finalGoal"),p.s("goalGroup","habit"));val primary=if(manual)p.s("goalGroup","habit") else result.s("primary");val target=if(primary==result.s("primary")&&result.i("recognized")>0)result.s("target") else if(manual)targets[primary]?:"general" else p.s("finalTarget").ifBlank{targets[primary]?:"general"};out.put("goalGroup",primary);out.put("finalTarget",target);out.put("goal",target);if(result.s("focus")!="full")out.put("focus",result.s("focus"));val restrictions=out.o("restrictions");for((k,v)in result.o("restrictions").entries())restrictions.put(k,v);out.put("restrictions",restrictions);out.put("interpretation374",result);out.put("goalAutoRestrictions374",arr(result.o("restrictions").entries().map{it.first}));return out}
 fun adjusted(p:JSONObject,titles:List<String> = emptyList()):JSONObject{val out=p.copyJson();val intent=interpret((listOf(p.s("finalGoal"))+titles).joinToString(". "),p.s("goalGroup","habit"));val target=if(intent.s("primary")==p.s("goalGroup")&&intent.i("recognized")>0)intent.s("target") else p.s("finalTarget",p.s("goal","general"));val plan=catalog.editorial.o("goalPlans").o(target);out.put("goal",plan.s("base",p.s("goal","general")));out.put("focus",if(intent.s("focus")!="full")intent.s("focus") else plan.s("focus",p.s("focus","full")));val r=out.o("restrictions");if(plan.b("noImpact"))r.put("noImpact",true);if(plan.b("seated"))r.put("seatedOnly",true);for((k,v)in intent.o("restrictions").entries())r.put(k,v);out.put("restrictions",r);if(out.s("trainingMode")=="routines")out.remove("dailyMissions");return out}
}
